<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); function sdfd($d){if(!$d)return '-';if(preg_match('/^(\d{4}-\d{2}-\d{2})/',$d,$m))return $m[1];return $d;} ?>
<div id="wrapper"><div class="content"><div class="panel_s"><div class="panel-body"><h4><i class="fa fa-truck"></i> خروج و ارسال کالا</h4><p class="text-muted">مدیریت یکپارچه مجوز خروج، خروج انبار، ارسال و تحویل مشتری</p><hr><table class="table dt-table"><thead><tr><th>فاکتور</th><th>مشتری</th><th>تاریخ</th><th>مبلغ</th><th>پرداخت‌شده</th><th>مانده</th><th>وضعیت مالی</th><th>وضعیت فرآیند</th><th>عملیات</th></tr></thead><tbody><?php foreach($invoices as $i){?><tr><td><?php echo html_escape($i['number']);?></td><td><?php echo html_escape($i['company']?:'-');?></td><td><?php echo html_escape($i['display_date']??'-');?></td><td><?php echo app_format_money($i['total'],'');?></td><td><?php echo app_format_money($i['paid'],'');?></td><td><?php echo app_format_money($i['remaining'],'');?></td><td><?php echo html_escape($i['payment_state']);?></td><td><?php echo html_escape($i['delivery_state']);?></td><td><a class="btn btn-default btn-sm" href="<?php echo admin_url('sales_delivery_flow/invoice/'.$i['id']);?>">مدیریت فرآیند</a></td></tr><?php }?></tbody></table></div></div></div></div><?php init_tail(); ?>
